// Presentation acknowledgements only. Never gates payouts, claims or chain reads.
import { CHAIN, CONTRACTS } from './chain-config.js';
const remembered = new Set();
const failedWrites = new Set();
function read(key) {
  if (!key) return false;
  try { if (globalThis.localStorage) {
    if (globalThis.localStorage.getItem(key) === '1') return true;
    if (!failedWrites.has(key)) return false;
  } } catch { /* memory fallback */ }
  return remembered.has(key);
}
function write(key) {
  if (!key) return;
  remembered.add(key);
  try { globalThis.localStorage?.setItem(key, '1'); failedWrites.delete(key); }
  catch { failedWrites.add(key); }
}
export function crapsResolutionSeenKey(address, battleKey, viewerBetId, chainId = CHAIN.id, contract = CONTRACTS.CRAPS) {
  return ['craps-resolution-seen:v2', String(chainId ?? ''), String(contract ?? '').toLowerCase(),
    String(address || '').toLowerCase(), String(battleKey || '').toLowerCase(), String(viewerBetId || '')].join(':');
}
export function hasViewedBattle(address, replay) {
  return read(crapsResolutionSeenKey(address, replay?.battleKey, replay?.viewerBetId, replay?.chainId, replay?.contract));
}
export function markBattleViewed(address, replay) {
  const key = crapsResolutionSeenKey(address, replay?.battleKey, replay?.viewerBetId, replay?.chainId, replay?.contract);
  const seen = read(key);
  write(key);
  if (!seen && typeof globalThis.CustomEvent === 'function') {
    globalThis.document?.dispatchEvent?.(new CustomEvent('craps:replay-viewed'));
  }
}
function jackpotKey(player, day) {
  const address = String(player || '').toLowerCase();
  if (!/^0x[0-9a-f]{40}$/.test(address) || !Number.isInteger(Number(day)) || Number(day) <= 0) return null;
  return `jackpot-viewed:v1:${CHAIN.id}:${String(CONTRACTS.GAME).toLowerCase()}:${address}:${Number(day)}`;
}
export function hasViewedJackpot(player, day) {
  const key = jackpotKey(player, day);
  // Keep already completed draws quiet when upgrading from the original board.
  return Boolean(key && (read(key) || read(`jackpot_complete_day_${CHAIN.id}_${Number(day)}`) || read(`spun_day_${CHAIN.id}_${Number(day)}`)));
}
export function markJackpotViewed(player, day) { write(jackpotKey(player, day)); }
